\label{metric}
The metric $g=\kappa^2(s)(ds^2+I_{-\epsilon}^{n-1})$ given above is
of constant scalar curvature $R$ if and only if the function $\kappa(s)$ satisfies
$$ -\frac{\kappa_{ss}}{\kappa^3}+\frac{(n+2)\kappa_s^2}{2\kappa^4}+\epsilon\frac{n-2}{2\kappa^2}
=R,~~~~\kappa_s=\frac{d}{ds}\kappa.$$

\label{le1}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a conformally flat
hypersurface without umbilical points. If the M\"{o}bius scalar curvature is constant,  then we can choose a local orthonormal
basis $\{E_1,\cdots,E_n\}$ with
respect to the M\"{o}bius metric $g$ such that
\begin{equation}\label{bbcc}
(B_{ij})=diag\{\frac{n-1}{n},\frac{-1}{n},\cdots,\frac{-1}{n}\},~~
(A_{ij})=diag\{a_1,a_2,\cdots,a_2\}.
\end{equation}
Moreover, the distribution $\mathbb{D}=span\{E_2,\cdots,E_n\}$ is integrable.

Using
$dB_{ij}+\sum_kB_{kj}\omega_{ki}+\sum_kB_{ik}\omega_{kj}=\sum_kB_{ij,k}\omega_k$
, the equation (\ref{equa3}), we get
\begin{equation}\label{a1}
\begin{split}
&B_{1\alpha,\alpha}=-C_1, ~~otherwise, ~~~B_{ij,k}=0;\\
&\omega_{1\alpha}=-C_1\omega_{\alpha},~~~~C_{\alpha}=0.
\end{split}
\end{equation}

Thus $d\omega_1=0$ and the distribution $\mathbb{D}=span\{E_2,\cdots,E_n\}$ is
integrable.

Using $dC_i+\sum_kC_k\omega_{ki}=\sum_kC_{i,k}\omega_k$ and
(\ref{a1}), we can obtain
\begin{equation}\label{c2}
C_{\alpha,\alpha}=-C_1^2, ~~~C_{\alpha,k}=0,\alpha\neq k.
\end{equation}
From (\ref{a1}),
\begin{equation*}
\begin{split}
&d\omega_{1\alpha}=-dC_1\wedge\omega_{\alpha}-C_1d\omega_{\alpha}\\
&=-dC_1\wedge\omega_{\alpha}+C_1^2\omega_1\wedge\omega_{\alpha}-C_1\sum_{\gamma}\omega_{\gamma}\wedge\omega_{\gamma\alpha},
\end{split}
\end{equation*}
and
$d\omega_{1\alpha}-\sum_j\omega_{1j}\wedge\omega_{j\alpha}=-\frac{1}{2}\sum_{kl}R_{1\alpha
kl}\omega_k\wedge\omega_l$, we get that
\begin{equation}\label{c1}
R_{1\alpha
1\alpha}=C_{1,1}-C_1^2,~~~~R_{1\alpha\beta\alpha}-C_{1,\beta}=0.
\end{equation}
Since $R_{1\alpha
1\alpha}=-\frac{n-1}{n^2}+a_1+a_{\alpha}=C_{1,1}-C_1^2$ and
$R_{1\alpha\beta\alpha}=A_{1\beta},\alpha\neq\beta$, thus we have
\begin{equation}\label{a2}
a_2=a_3=\cdots=a_n,~~~~ A_{1\beta}=C_{1,\beta}.
\end{equation}
Thus $A|_{\mathbb{D}}=aI,~~a=a_2$. Since $E_1$ is principal vector field, then vector $E=A_{12}E_2+\cdots+A_{1n}E_n$ is well defined.
If $E=0$, then $A_{12}=\cdots=A_{1n}=0$. If $E\neq 0$,
we can rechoose a local orthonormal basis  $\{\tilde{E}_2=\frac{E}{|E|},\tilde{E}_3,\cdots,\tilde{E}_n\}$ of $\mathbb{D}$ with
respect to the M\"{o}bius metric $g$ such that
\begin{equation}\label{bba}
(B_{ij})=diag(\frac{n-1}{n},\frac{-1}{n},\cdots,\frac{-1}{n}),~~
(A_{ij})=\left(
  \begin{array}{ccccc}
    A_{11} & A_{12} & 0 & \cdots & 0 \\
    A_{21} & a_2 & 0 & \cdots & 0 \\
    0& 0 & a_2& \cdots & 0 \\
    \vdots & \vdots & \vdots& \ddots & \vdots \\
   0 & 0 & 0 & \cdots &a_2 \\
  \end{array}
\right)
\end{equation}

To finish the proof of the Lemma, we need to prove that $A_{12}=0$.
Using $dA_{ij}+\sum_kA_{kj}\omega_{ki}+\sum_kA_{ik}\omega_{kj}=\sum_kA_{ij,k}\omega_k$
, the equation (\ref{equa1}) and (\ref{bba}), we get
\begin{equation}\label{aa}
\begin{split}
&\sum_mA_{12,m}\omega_m=dA_{12}+(A_{11}-A_{22})\omega_{12},\\
&\sum_mA_{1\alpha,m}\omega_m=(A_{11}-a_2)\omega_{1\alpha}+A_{12}\omega_{2\alpha},~~\sum_mA_{2\alpha,m}\omega_m=A_{12}\omega_{1\alpha},~~\alpha\geq3,\\
&\sum_kA_{11,k}\omega_k=dA_{11}+2A_{12}\omega_{21}, ~~\sum_kA_{22,k}\omega_k=dA_{22}+2A_{12}\omega_{12},\\
&\sum_kA_{\alpha\alpha,k}\omega_k=dA_{\alpha\alpha},~~A_{\alpha\beta,k}=0, ~~\alpha\neq\beta, ~~\alpha,\beta\geq 3.
\end{split}
\end{equation}
From the fourth and seventh equation in (\ref{aa}), we get
\begin{equation}\label{aad}
E_{\alpha}(a_2)=A_{\beta\beta,\alpha}=A_{\beta\alpha,\beta}=0, ~~~\alpha\geq 3.
\end{equation}
Since the M\"{o}bius scalar curvature is constant, $tr(A)=A_{11}+(n-1)a_2$ is constant. Thus
\begin{equation}\label{aad1}
A_{1\alpha,1}=A_{11,\alpha}=E_{\alpha}(A_{11})=0,~~~\alpha\geq 3.
\end{equation}
From the first, second and third  equation in (\ref{aa}), we get
\begin{equation}\label{aad2}
A_{12,2}=E_2(A_{12})-(A_{11}-a_2)C_1,~~~A_{1\beta,\beta}=-(A_{11}-a_2)C_1+A_{12}\omega_{2\beta}(E_{\beta}).
\end{equation}
On the other hand, From (\ref{equa1}), we have
\begin{equation*}
\begin{split}
&E_1(A_{22})=A_{22,1}=A_{12,2}+\frac{1}{n}C_1=E_2(A_{12})-(A_{11}-a_2)C_1+\frac{1}{n}C_1,\\
&E_1(A_{\alpha\alpha})=A_{\alpha\alpha,1}=A_{1\alpha,\alpha}+\frac{1}{n}C_1=-(A_{11}-a_2)C_1+A_{12}\omega_{2\beta}(E_{\beta})+\frac{1}{n}C_1,\\
\end{split}
\end{equation*}
which implies that
\begin{equation}\label{2w}
E_2(A_{12})=A_{12}\omega_{2\beta}(E_{\beta}).
\end{equation}
Since $A_{1\alpha,\beta}=A_{\alpha\beta,1}=A_{1\beta,1}=A_{12,\alpha}=0,~\alpha\neq\beta$, from the second equation in (\ref{aa}) we can obtain
\begin{equation}\label{aa4}
A_{12}\omega_{2\beta}(E_k)=0, ~~\beta\geq 3,~~k\neq\beta.
\end{equation}
From the first and third  equation in (\ref{aa}), we get
\begin{equation}\label{aa1}
\begin{split}
E_2(a_2)&=E_2(A_{\beta\beta})=A_{\beta\beta,2}=A_{2\beta,\beta}=-A_{12}C_1,\\
E_1(A_{12})&=A_{12,1}=A_{11,2}=E_2(A_{11})+2A_{12}C_1\\
&=E_2(-(n-1)a_2)+2A_{12}C_1=(n+1)A_{12}C_1.
\end{split}
\end{equation}
Now we assume that $A_{12}\neq 0,$ From (\ref{2w}) and (\ref{aa4}), we have
$$\omega_{2\alpha}=\frac{E_2(A_{12})}{A_{12}}\omega_{\alpha}:=\mu\omega_{\alpha},~~\alpha\geq 3.$$
Thus
\begin{equation*}
\begin{split}
&d\omega_{2\alpha}=d\mu\wedge\omega_{\alpha}+\mu d\omega_{\alpha}\\
&=d\mu\wedge\omega_{\alpha}-\mu C_1^2\omega_1\wedge\omega_{\alpha}+\mu^2\omega_2\wedge\omega_{\alpha}
+\mu\sum_{\gamma\geq3}\omega_{\gamma}\wedge\omega_{\gamma\alpha}.
\end{split}
\end{equation*}
Using
$d\omega_{2\alpha}-\sum_j\omega_{2j}\wedge\omega_{j\alpha}=-\frac{1}{2}\sum_{kl}R_{2\alpha
kl}\omega_k\wedge\omega_l$, we get that
$$E_(\mu)-\mu C_1=-A_{12}.$$
On the other hand, using (\ref{a1}) and (\ref{aa1}), we have
\begin{equation*}
\begin{split}
E_1(\mu)&=E_1\big[\frac{E_2(A_{12})}{A_{12}}\big]=\frac{E_1E_2(A_{12})}{A_{12}}-\frac{E_2(A_{12})E_1(A_{12})}{A_{12}^2}\\
&=\frac{E_1E_2(A_{12})}{A_{12}}-(n+1)\frac{E_2(A_{12})C_1}{A_{12}}\\
&=\frac{(E_2E_1+C_1E_2)(A_{12})}{A_{12}}-(n+1)\frac{E_2(A_{12})C_1}{A_{12}}\\
&=\frac{E_2[(n+1)A_{12}C_1]}{A_{12}}-n\frac{E_2(A_{12})C_1}{A_{12}}\\
&=(n+1)C_{1,2}+\frac{E_2(A_{12})C_1}{A_{12}},
\end{split}
\end{equation*}
which implies that
$$(n+1)C_{1,2}=-A_{12}.$$
This is a contradiction by $A_{12}=C_{1,2}$. Therefore $A_{12}=0$ and we finish the proof.

\label{le2}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then under the local orthonormal
basis $\{E_1,\cdots,E_n\}$ in Lemma \ref{le1}, we have
\begin{equation}\label{aa11}
\begin{split}
&a_1=\frac{2n-1}{2n^2}-\frac{R}{2(n-1)(n-2)}+\frac{n-1}{n-2}(C_{1,1}-C_1^2),\\
&a_2=\frac{R}{2(n-1)(n-2)}-\frac{1}{2n^2}-\frac{1}{n-2}(C_{1,1}-C_1^2),\\
&A_{\alpha\alpha,1}=\frac{R}{(n-1)(n-2)}C_1-\frac{n}{n-2}(C_1C_{1,1}-C_1^3).
\end{split}
\end{equation}
Except these coefficients $A_{11,1}, A_{1\alpha,\alpha}$ and $A_{\alpha\alpha,1}$ the coefficients of $\nabla A$
are equal to zero.

\label{lec2}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then under the local orthonormal
basis $\{E_1,\cdots,E_n\}$ in Lemma \ref{le1}, we have
\begin{equation}\label{cc11}
\begin{split}
&C_{1,11}=E_1(C_{1,1})=(n+2)C_1C_{1,1}-nC_1^3-\frac{R}{n-1}C_1,\\
&C_{\alpha,\alpha1}=E_1(C_{\alpha,\alpha})=-2C_1C_{1,1},~~C_{1,\alpha\alpha}=C_{\alpha,1\alpha}=-(C_{1,1}+C_1^2)C_1.
\end{split}
\end{equation}
Except these coefficients $C_{1,11}, C_{1,\alpha\alpha}$ and $C_{\alpha,\alpha1}$ the coefficients of $\nabla^2C$
are equal to zero.

\label{les2}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then under the local orthonormal
basis $\{E_1,\cdots,E_n\}$ in Lemma \ref{le1}, the coefficients of $\nabla^2S$ satisfy
\begin{equation}\label{ss11}
\begin{split}
&S_{11,11}=-RC_{1,1}+n(n-1)C_{1,1}^2+n(n-1)^2C_1^2C_{1,1}-n^2(n-1)C_1^4-nRC_1^2,\\
&S_{11,\alpha\alpha}=\frac{(n+1)R}{n-1}C_1^2-n(n+1)[C_1^2C_{1,1}-C_1^4],~~S_{\alpha\alpha,11}=-(n-1)S_{11,11},\\
&S_{\alpha\alpha,\alpha\alpha}=3S_{\alpha\alpha,\beta\beta}=3\{\frac{-R}{n-1}C_1^2+n[C_1^2C_{1,1}-C_1^4]\},~~\alpha\neq\beta.
\end{split}
\end{equation}

\label{le3}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a compact conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then
\begin{equation}\label{le33}
\begin{split}
&\int_{M^n}C_1^2C_{1,1}dV_g=\frac{n-1}{3}\int_{M^n}|C|^4dV_g,\\
&\int_{M^n}C_{1,1}^2dV_g=\int_{M^n}|C|^4dV_g+\frac{R}{n-1}\int_{M^n}|C|^2dV_g.
\end{split}
\end{equation}

Using the coefficients of the tensor $C$ and $S$,
 we define two smooth vector fields
$$X_S=\sum_{ij}C_iS_{ij}E_j, ~~X_C=\sum_{ij}C_iE_i.$$
From Lemma \ref{le1} and the equation (\ref{aa11}), we can get  the divergence of $X_S, X_C$,
\begin{equation*}
\begin{split}
&div X_C=\sum_iC_{i,i}=C_{1,1}-(n-1)C_1^2,\\
&div X_S=(n-1)(C_{1,1}^2-C_1^4-\frac{R}{n-1}C_1^2)+\frac{R}{2(n-1)}div X_C.
\end{split}
\end{equation*}
Since the hypersurface is compact, we have
\begin{equation}\label{int1}
\begin{split}
&\int_{M^n}C_{1,1}dV_g=(n-1)\int_{M^n}|C|^2dV_g,\\
&\int_{M^n}C_{1,1}^2dV_g=\int_{M^n}|C|^4dV_g+\frac{R}{n-1}\int_{M^n}|C|^2dV_g,
\end{split}
\end{equation}
On the other hand, we compute $\triangle |C|^2$,
\begin{equation*}
\begin{split}
&\triangle|C|^2=\sum_i(E_iE_i-\nabla_{E_i}E_i) |C|^2=\sum_i(E_iE_i-\nabla_{E_i}E_i)C_1^2\\
&=E_1E_1(C_1^2)-\sum_i\nabla_{E_i}E_i(C_1^2)=2C_{1,1}^2+2C_1C_{1,11}-2(n-1)C_1^2C_{1,1}\\
&=2C_{1,1}^2+6C_1^2C_{1,1}-2nC_1^4-\frac{2R}{n-1}C_1^2.
\end{split}
\end{equation*}
Since the hypersurface is compact, we have
$$\int_{M^n}C_{1,1}^2dV_g+3\int_{M^n}C_1^2C_{1,1}dV_g-n\int_{M^n}C_1^4dV_g-\frac{R}{n-1}\int_{M^n}|C|^2dV_g=0.$$
Combining the equation (\ref{int1}), we can derive the first equation in (\ref{le33}).

\label{inte01}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a compact conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then
\begin{equation}\label{inte011}
\int_{M^n}\big\{C_{1,1}^3+(n+5)C_1^2C_{1,1}^2-(2n+5)C_1^4C_{1,1}+(n-1)C_1^6-\frac{2R}{3}C_1^4\big\}dV_g=0.
\end{equation}

Using the coefficients of the tensor $C$ and $S$,
 we define a smooth vector field
$$Y_S=\sum_{ijk}C_{i,j}S_{ij,k}E_k.$$
Using Lemma \ref{lec2} and the equation (\ref{ss11}), we compute  the divergence of $Y_S$,
\begin{equation*}
\begin{split}
&\frac{1}{n(n-1)}div Y_S=\sum_{ijk}C_{i,jk}S_{ij,k}+\sum_{ijk}C_{i,j}S_{ij,kk},\\
&=C_{1,1}^3+(n+5)C_1^2C_{1,1}^2-(2n+5)C_1^4C_{1,1}+(n-1)C_1^6+\frac{(2n-1)R}{n(n-1)}C_1^4\\
&-\frac{R}{n(n-1)}C_{1,1}^2-\frac{2(n+3)R}{n(n-1)}C_1^2C_{1,1}+\frac{R^2}{n(n-1)^2}C_1^2.
\end{split}
\end{equation*}
Integrating this equation and using (\ref{le33}), we can derive the second equation in (\ref{inte011}).

\label{inte1}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a compact conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then
\begin{equation}\label{inte11}
\begin{split}
&\int_{M^n}\big\{C_1^2C_{1,1}^2+C_1^4C_{1,1}-\frac{n}{3}C_1^6-\frac{R}{3(n-1)}C_1^4\big\}dV_g=0,\\
&\int_{M^n}\big\{C_{1,1}^3+(n-1)C_1^2C_{1,1}^2-(2n+1)C_1^4C_{1,1}+(n+1)C_1^6+\frac{2(n+1)R}{3(n-2)}C_1^4\big\}dV_g=0.
\end{split}
\end{equation}

Using (\ref{cc11}),
\begin{equation*}
\begin{split}
\frac{1}{4}\triangle |C|^4&=\frac{1}{4}\sum_i(E_iE_i-\nabla E_i{E_i})|C|^4=3C_1^2C_{1,1}^2+C_1^3C_{1,11}-(n-1)C_1^4C_{1,1}\\
&=3C_1^2C_{1,1}^2+3C_1^4C_{1,1}-nC_1^6-\frac{R}{n-1}C_1^4.
\end{split}
\end{equation*}
Since the hypersurface is compact, then
$$\int_{M^n}\{3C_1^2C_{1,1}^2+3C_1^4C_{1,1}-nC_1^6-\frac{R}{n-1}C_1^4\}dV_g=0.$$
Since $S_{ij}$ is a Codazzi tensor and $tr(S)$ is constant, we can compute $\triangle |S|^2$ by (\ref{sij}),
\begin{equation*}
\begin{split}
&\frac{1}{n^2(n-1)}\triangle |S|^2=\frac{1}{2n^2(n-1)}\{\sum_{ijk}|S_{ij,k}|^2+\frac{1}{2}\sum_{ij}(S_i-S_j)^2R_{ijij}\}\\
&=C_{1,1}^3-(2n+1)C_1^4C_{1,1}+(n-1)C_1^2C_{1,1}^2-\frac{2R}{n-1}C_1^2C_{1,1}-\frac{2R}{n(n-1)}C_{1,1}^2\\
&+(n+1)C_1^6+\frac{2(n+1)R}{n(n-1)}C_1^4+\frac{(n+1)R^2}{n^2(n-1)^2}C_1^2+\frac{R^2}{n^2(n-1)^2}C_{1,1}.
\end{split}
\end{equation*}
Integrating this equation and using (\ref{le33}), we can derive the second equation in (\ref{inte11}).

\label{inte2}
Let $f: M^n\rightarrow \mathbb{S}^{n+1}$ $(n\geq 4)$ be a compact conformally flat
hypersurface without umbilical points everywhere. If the M\"{o}bius scalar curvature $R$ is constant.
then
\begin{equation}\label{inte21}
\begin{split}
&\int_{M^n}\big\{C_{1,1}^3+\frac{5n+4}{2}C_1^2C_{1,1}^2-3(n+1)C_1^4C_{1,1}+\frac{n}{2}C_1^6-\frac{(7n-10)R}{3(n-2)}C_1^4\big\}dV_g=0£¬\\
&\int_{M^n}\big\{C_{1,1}^3+\frac{5n+16}{2}C_1^2C_{1,1}^2-3(n-1)C_1^4C_{1,1}-\frac{3n}{2}C_1^6-\frac{(7n+2)R}{6(n-1)}C_1^4\big\}dV_g=0.
\end{split}
\end{equation}

Using the coefficients of the tensor $C$ and $A$, we have two following smooth functions,
$$|C|^2_A=\sum_{ij}C_iA_{ij}C_j=C_1^2a_1, ~~|C|^2_C=\sum_{ij}C_iC_{i,j}C_j=C_1^2C_{1,1}.$$
Next we compute $\triangle (|C|^2_A)$ and $\triangle(|C|^2_C)$.
\begin{equation*}
\begin{split}
&\frac{n-2}{2(n-1)}\triangle (|C|^2_A)=\frac{n-2}{2(n-1)}(E_1E_1(C_1^2a_1)-(n-1)C_1E_1(C_1^2a_1))\\
&=C_{1,1}^3-3(n+1)C_1^4C_{1,1}+\frac{(5n+4)}{2}C_1^2C_{1,1}^2+\frac{n}{2}C_1^6\\
&+\frac{n-2}{2(n-1)}[\frac{2n-1}{n^2}-\frac{R}{(n-1)(n-2)}]C_{1,1}^2-\frac{n-2}{2(n-1)}[\frac{2n-1}{n}-\frac{(2n-1)R}{(n-1)(n-2)}]C_1^4\\
&\frac{n-2}{2(n-1)}[\frac{3(2n-1)}{n^2}-\frac{(7n-4)R}{(n-1)(n-2)}]C_1^2C_{1,1}\\
&-\frac{n-2}{2(n-1)}[\frac{2n-1}{n^2}-\frac{R}{(n-1)(n-2)}]\frac{R}{n-1}C_1^2.
\end{split}
\end{equation*}
Integrating this equation and using (\ref{le33}), we can derive the first equation in (\ref{inte21}).
\begin{equation*}
\begin{split}
&\frac{1}{2}\triangle (|C|^2_C)=\frac{1}{2}(E_1E_1(C_1^2C_{1,1})-(n-1)C_1E_1(C_1^2C_{1,1}))\\
&=C_{1,1}^3-3(n-1)C_1^4C_{1,1}+\frac{(5n+16)}{2}C_1^2C_{1,1}^2-\frac{3n}{2}C_1^6\\
&-\frac{7R}{2(n-1)}C_1^2C_{1,1}-\frac{3R}{2(n-1)}C_1^4.
\end{split}
\end{equation*}
Integrating this equation and using (\ref{le33}), we can derive the second equation in (\ref{inte21}).
